import numpy as np
import pandas as pd
import json
import os
from scipy import stats, optimize as sp_opt, integrate

OUT_DIR = os.environ.get("T1_OUT", "/app/output")
os.makedirs(OUT_DIR, exist_ok=True)

# (no input data: every sample is generated from the pinned RandomState(42))

# Step 1: Data Generation
rng = np.random.RandomState(42)
N = 10000

# Normal
normal_samples = rng.standard_normal(N)

# Student-t with nu=5
student_t_samples = rng.standard_t(df=5, size=N)

# Contaminated Normal: N(0,1) with prob 0.95, N(0,9) with prob 0.05
u = rng.uniform(0, 1, size=N)
mask = u < 0.95
contaminated_samples = np.where(
    mask,
    rng.standard_normal(N),
    rng.normal(0, 3, size=N)
)

distributions = {
    "normal": normal_samples,
    "student_t": student_t_samples,
    "contaminated_normal": contaminated_samples,
}

# Step 2: True Risk Measures
# Loss distribution: losses = -returns, so VaR_alpha = -quantile_alpha(returns)
# Since we want VaR as a positive loss value:
#   VaR_alpha(loss) = -quantile(1-alpha)(returns) = quantile(alpha)(-returns)

alphas = [0.95, 0.99]

def normal_var_true(alpha):
    # VaR at level alpha for N(0,1) losses = -z_{1-alpha} = z_alpha
    return stats.norm.ppf(alpha)

def normal_es_true(alpha):
    # ES_alpha = phi(z_alpha)/(1-alpha)
    z = stats.norm.ppf(alpha)
    return stats.norm.pdf(z) / (1 - alpha)

def student_t_var_true(alpha, nu=5):
    return stats.t.ppf(alpha, df=nu)

def student_t_es_true(alpha, nu=5):
    # ES = (g_{nu-1}(t_alpha) / (1-alpha)) * sqrt((nu-2)/nu) * ...
    # For standardized Student-t: pdf at quantile
    t_q = stats.t.ppf(alpha, df=nu)
    # E[X | X > t_q] for standardized t with nu df:
    # = (f(t_q)/(1-alpha)) * (nu + t_q^2)/(nu - 1)
    pdf_q = stats.t.pdf(t_q, df=nu)
    return pdf_q / (1 - alpha) * (nu + t_q**2) / (nu - 1)

def contaminated_var_true(alpha):
    # Mixture CDF: F(x) = 0.95 * Phi(x/sqrt(1)) + 0.05 * Phi(x/3)
    def cdf(x):
        return 0.95 * stats.norm.cdf(x, 0, 1) + 0.05 * stats.norm.cdf(x, 0, 3)
    # Find x such that F(x) = alpha
    # Use root finding
    def f(x):
        return cdf(x) - alpha
    # Bracket
    lo, hi = -10, 20
    sol = sp_opt.brentq(f, lo, hi)
    return sol

def contaminated_es_true(alpha):
    var = contaminated_var_true(alpha)
    # ES = (1/(1-alpha)) * integral_{var}^{inf} x * f(x) dx
    # f(x) = 0.95 * phi(x, 0, 1) + 0.05 * phi(x, 0, 3)
    def integrand(x):
        f_x = 0.95 * stats.norm.pdf(x, 0, 1) + 0.05 * stats.norm.pdf(x, 0, 3)
        return x * f_x
    val, _ = integrate.quad(integrand, var, np.inf)
    return val / (1 - alpha)

true_values = {
    "normal": {},
    "student_t": {},
    "contaminated_normal": {},
}
for a in alphas:
    true_values["normal"][str(a)] = {
        "var": float(normal_var_true(a)),
        "es": float(normal_es_true(a)),
    }
    true_values["student_t"][str(a)] = {
        "var": float(student_t_var_true(a)),
        "es": float(student_t_es_true(a)),
    }
    true_values["contaminated_normal"][str(a)] = {
        "var": float(contaminated_var_true(a)),
        "es": float(contaminated_es_true(a)),
    }

with open(os.path.join(OUT_DIR, "true_values.json"), "w") as f:
    json.dump(true_values, f, indent=2)

# Step 3: Estimation Methods
def historical_method(samples, alpha):
    var_est = np.quantile(samples, alpha, method='linear')
    tail = samples[samples >= var_est]
    if len(tail) == 0:
        es_est = var_est
    else:
        es_est = np.mean(tail)
    return float(var_est), float(es_est)

def parametric_normal_method(samples, alpha):
    mu = np.mean(samples)
    sigma = np.std(samples, ddof=0)
    var_est = stats.norm.ppf(alpha, loc=mu, scale=sigma)
    z = (var_est - mu) / sigma
    es_est = mu + sigma * stats.norm.pdf(z) / (1 - alpha)
    return float(var_est), float(es_est)

def parametric_t_method(samples, alpha):
    nu, loc, scale = stats.t.fit(samples)
    var_est = stats.t.ppf(alpha, df=nu, loc=loc, scale=scale)
    # ES via numerical integration of x*f(x) / (1-alpha)
    def integrand(x):
        return x * stats.t.pdf(x, df=nu, loc=loc, scale=scale)
    val, _ = integrate.quad(integrand, var_est, np.inf)
    es_est = val / (1 - alpha)
    return float(var_est), float(es_est)

def kernel_density_method(samples, alpha):
    kde = stats.gaussian_kde(samples, bw_method='silverman')
    # Fine grid for CDF evaluation
    x_min = np.min(samples) - 5 * np.std(samples)
    x_max = np.max(samples) + 5 * np.std(samples)
    grid = np.linspace(x_min, x_max, 100000)
    pdf_vals = kde(grid)
    cdf_vals = np.cumsum(pdf_vals)
    cdf_vals /= cdf_vals[-1]
    # Find alpha-quantile by interpolation
    var_est = float(np.interp(alpha, cdf_vals, grid))
    # ES via numerical integration
    mask_tail = grid >= var_est
    grid_tail = grid[mask_tail]
    pdf_tail = pdf_vals[mask_tail]
    val = np.trapezoid(grid_tail * pdf_tail, grid_tail)
    es_est = val / (1 - alpha)
    return float(var_est), float(es_est)

method_funcs = {
    "historical": historical_method,
    "parametric_normal": parametric_normal_method,
    "parametric_t": parametric_t_method,
    "kernel_density": kernel_density_method,
}

rows = []
for dist_name, samples in distributions.items():
    for method_name, method_fn in method_funcs.items():
        for a in alphas:
            var_est, es_est = method_fn(samples, a)
            rows.append({
                "distribution": dist_name,
                "method": method_name,
                "alpha": a,
                "var_estimate": var_est,
                "es_estimate": es_est,
            })

estimates_df = pd.DataFrame(rows)
estimates_df.to_csv(os.path.join(OUT_DIR, "estimates.csv"), index=False)

# Step 4: Comparison
method_rmse = {}
for method_name in method_funcs:
    sub = estimates_df[estimates_df["method"] == method_name]
    var_errors = []
    es_errors = []
    for _, row in sub.iterrows():
        dist_name = row["distribution"]
        a_key = str(row["alpha"])
        true_var = true_values[dist_name][a_key]["var"]
        true_es = true_values[dist_name][a_key]["es"]
        var_errors.append((row["var_estimate"] - true_var)**2)
        es_errors.append((row["es_estimate"] - true_es)**2)
    var_rmse = float(np.sqrt(np.mean(var_errors)))
    es_rmse = float(np.sqrt(np.mean(es_errors)))
    method_rmse[method_name] = {
        "var_rmse": var_rmse,
        "es_rmse": es_rmse,
    }

best_method_per_distribution = {}
for dist_name in distributions.keys():
    sub = estimates_df[estimates_df["distribution"] == dist_name]
    method_total = {}
    for method_name in method_funcs:
        msub = sub[sub["method"] == method_name]
        var_errors = []
        es_errors = []
        for _, row in msub.iterrows():
            a_key = str(row["alpha"])
            true_var = true_values[dist_name][a_key]["var"]
            true_es = true_values[dist_name][a_key]["es"]
            var_errors.append((row["var_estimate"] - true_var)**2)
            es_errors.append((row["es_estimate"] - true_es)**2)
        method_total[method_name] = np.sqrt(np.mean(var_errors)) + np.sqrt(np.mean(es_errors))
    best_method_per_distribution[dist_name] = min(method_total, key=method_total.get)

comparison = {
    "method_rmse": method_rmse,
    "best_method_per_distribution": best_method_per_distribution,
}

with open(os.path.join(OUT_DIR, "comparison.json"), "w") as f:
    json.dump(comparison, f, indent=2)

# Step 5: Summary
overall_totals = {}
for method_name in method_funcs:
    overall_totals[method_name] = method_rmse[method_name]["var_rmse"] + method_rmse[method_name]["es_rmse"]
overall_best = min(overall_totals, key=overall_totals.get)

summary = {
    "n_samples": 10000,
    "seed": 42,
    "alpha_levels": [0.95, 0.99],
    "distributions": ["normal", "student_t", "contaminated_normal"],
    "methods": ["historical", "parametric_normal", "parametric_t", "kernel_density"],
    "overall_best_method": overall_best,
}

with open(os.path.join(OUT_DIR, "summary.json"), "w") as f:
    json.dump(summary, f, indent=2)


# identities (print only)
for d in true_values:
    for a in true_values[d]:
        print(d, a, "ES>=VaR:", true_values[d][a]["es"] >= true_values[d][a]["var"])
print(estimates_df.to_string())
print(json.dumps(comparison, indent=2), json.dumps(summary, indent=2))
